export function fixturePage(url) {
  const parsed = new URL(url, 'http://localhost:4173');
  const section = parsed.pathname.match(/section\/(\d+)/)?.[1] ?? '1';
  const mode = parsed.searchParams.get('case') ?? 'all';
  const short = `<article data-zf-activity="short" data-kind="short_answer" data-category="participation" data-revision="0"><h2>03 · Short answer</h2><div data-question="s1"><p>Keep whitespace and map fields by ID.</p><label>Code<textarea data-field="code"></textarea></label><label>Number<input data-field="number"></label><button data-role="reveal" data-control="reveal:s1" aria-expanded="false">Show answer</button><div data-answers hidden><span data-answer-for="number"><span data-alternative>7</span><span data-alternative>07</span></span><pre data-answer-for="code">  x &lt; 7;\n    next();</pre></div><button data-role="submit" data-control="submit:s1">Check answer</button><output data-feedback="none"></output></div></article>`;
  const choice = `<article data-zf-activity="choice" data-kind="single_choice" data-category="participation" data-revision="0"><h2>02 · Multiple choice</h2><div data-question="q1" data-question-type="single"><p>Which number is even?</p><button data-control="q1:a" data-choice="a">3</button><button data-control="q1:b" data-choice="b">4</button><button data-control="q1:c" data-choice="c">5</button><output data-feedback="none"></output></div></article>`;
  const animation = `<article data-zf-activity="animation" data-kind="animation" data-category="participation" data-revision="0" data-player="ready"><h2>01 · Animation</h2><p>A two-step demonstration.</p><button data-control="speed" aria-pressed="false">2× speed</button><button data-control="start">Start</button><button data-control="next" disabled>Next step</button><output data-feedback="none"></output></article>`;
  const matching = `<article data-zf-activity="matching" data-kind="matching" data-category="participation" data-revision="0" data-interaction="html-dnd"><h2>04 · Term matching</h2><p>Visible mapping: A → one, B → two.</p><span data-map-source="a" data-map-target="one"></span><span data-map-source="b" data-map-target="two"></span><div class="columns"><div><div draggable="true" data-source="a">A</div><div draggable="true" data-source="b">B</div></div><div><div data-target="one">One</div><div data-target="two">Two</div></div></div><output data-feedback="none"></output></article>`;
  const ordered = `<article data-zf-activity="order" data-kind="ordered_blocks" data-category="participation" data-revision="0"><h2>05 · Ordered blocks</h2><p>Visible solution: first, second (indent 1). Duplicate text has distinct IDs.</p><div data-solution><span data-order-id="first" data-indent="0"></span><span data-order-id="second" data-indent="1"></span></div><div data-block="first" data-position="-1" data-indent="0">step();</div><div data-block="second" data-position="-1" data-indent="0">step();</div><div data-block="unused" data-position="-1" data-indent="0" data-distractor="true">unused();</div><button data-control="place:first:0">Place first at 0</button><button data-control="place:second:1">Place second at 1</button><button data-control="indent:second">Indent second</button><button data-control="outdent:second">Outdent second</button><button data-control="check-order">Check order</button><output data-feedback="none"></output></article>`;
  let activities = section === '1' ? animation + choice + short + matching + ordered : choice;
  if (mode === 'empty') activities = '';
  if (['slow', 'offline', 'rerender', 'navigation', 'spa', 'manual'].includes(mode))
    activities = choice;
  if (mode === 'complete')
    activities = short.replace('data-revision="0"', 'data-revision="0" data-complete="true"');
  if (mode === 'unknown')
    activities = `<article data-zf-activity="unknown" data-kind="lab" data-category="challenge"><h2>Unsupported challenge</h2><input type="radio" id="unrelated"></article>`;
  if (mode === 'missing')
    activities = short
      .replace('data-field="code"', 'data-missing="code"')
      .replace('data-field="number"', 'data-missing="number"');
  return `<!doctype html><html lang="en"><head><meta charset="UTF-8"><title>ZyFlow fixture lab</title><link rel="stylesheet" href="/fixture.css"></head><body data-case="${mode.replace(/[^a-z]/g, '')}"><main data-zf-section="1.${section}" data-ready="true"><p class="eyebrow">ZYFLOW / SYNTHETIC FIXTURE LAB</p><h1>Section 1.${section}</h1><p>This page contains original synthetic exercises for extension testing.</p>${activities}${Number(section) < 3 ? `<a data-zf-next href="/zybook/demo/chapter/1/section/${Number(section) + 1}?case=${mode}">Next section →</a>` : '<p>End of book.</p>'}</main><script src="/site.js"></script></body></html>`;
}
